#!/usr/bin/env python3
"""Create a standalone UI preview using the actual Android assets and explicit demo data."""
from pathlib import Path
import argparse
root=Path(__file__).resolve().parent
assets=root/'assets'
p=argparse.ArgumentParser()
p.add_argument('--output',default=str(root.parent.parent/'Setwerk-Musik-Vorschau.html'))
a=p.parse_args()
EXTRA_CSS='\n#preview-bar{background:#eff4e8;color:#18231c;padding:12px 20px;display:flex;align-items:center;gap:14px;flex-wrap:wrap;font:12px/1.5 system-ui}#preview-bar label{display:flex;align-items:center;gap:8px}#preview-bar select{font:inherit;width:auto;padding:5px 10px;background:white;border:1px solid #c9d4c8;border-radius:7px}#preview-bar p{margin:0;flex:1;min-width:220px}#preview-bar strong{font-weight:750}#app .focus-shell{min-height:calc(100dvh - 75px)}#preview-status{font-size:11px}'
BODY='<body><aside id="preview-bar"><p><strong>Vorschau · Musiksteuerung</strong><br>Interaktive Beispieldaten. Echte Musiksteuerung ist nur in der Android-Testversion verfügbar.</p><label>Musik-App stellt bereit<select id="preview-scenario"><option value="full">Steuerung + Warteschlange</option><option value="basic">Nur Steuerung</option><option value="access">Zugriff fehlt</option><option value="empty">Keine Musik aktiv</option></select></label></aside><div id="app"></div><dialog id="modal"></dialog><div id="toast" role="status"></div>'
FIXTURE="\nlet songs=[{id:'1',title:'Night Drive',artist:'Alex Morgan',duration:204000},{id:'2',title:'Momentum',artist:'Nova',duration:188000},{id:'3',title:'Second Wind',artist:'Daybreak',duration:221000},{id:'4',title:'Keep Moving',artist:'The Current',duration:197000}],songIndex=0,musicPlaying=true,musicPosition=64000,musicUpdated=Date.now(),scenario='full';\nfunction demoPosition(){return Math.min(songs[songIndex].duration,musicPosition+(musicPlaying?Date.now()-musicUpdated:0));}\nfunction demoState(){const song=songs[songIndex];return{supported:true,granted:scenario!=='access',active:scenario!=='empty',sessionKey:'preview:1',appName:'Beispieldaten',title:song.title,artist:song.artist,position:demoPosition(),duration:song.duration,playing:musicPlaying,speed:1,canPlay:true,canPause:true,canPrevious:songIndex>0,canNext:songIndex<songs.length-1,canSeek:true,next:scenario==='full'&&songs[songIndex+1]?songs[songIndex+1]:null,canRemoveNext:scenario==='full'};}\nwindow.SetwerkNative={call:async(operation,body={})=>{if(operation==='music-state')return demoState();musicPosition=demoPosition();musicUpdated=Date.now();if(operation==='music-pause')musicPlaying=false;else if(operation==='music-play')musicPlaying=true;else if(operation==='music-seek')musicPosition=body.position;else if(operation==='music-next'&&songIndex<songs.length-1){songIndex++;musicPosition=0;}else if(operation==='music-previous'&&songIndex>0){songIndex--;musicPosition=0;}else if(operation==='music-remove-next'&&songs[songIndex+1]?.id===body.nextId){songs.splice(songIndex+1,1);}else if(operation==='music-connect'){scenario='full';document.querySelector('#preview-scenario').value='full';}return{requested:true};}};\nconst initial=GymCore.fresh(),demoExercise=GYM_EXERCISES.find(ex=>/Bankdrücken/.test(ex.name)&&ex.kind==='reps')||GYM_EXERCISES[0],demoItem=GymCore.item(demoExercise,3,90);demoItem.sets.forEach(s=>{s.reps=10;s.weight=40;});initial.active=GymCore.start({name:'Ganzkörper',category:'Kraft',items:[demoItem]});\nwindow.AndroidGym={readState:()=>JSON.stringify(initial),writeState:()=>true,accountSettings:()=>{},scheduleRest:()=>{},cancelRest:()=>{},playRestStart:()=>{},setReminders:()=>{}};\ndocument.querySelector('#preview-scenario').addEventListener('change',event=>{scenario=event.target.value;SetwerkMusic.refresh();});\n"
def script(name):
    return '<script>'+(assets/name).read_text().replace('</script','<\\/script')+'</script>'
styles=(assets/'styles.css').read_text()+'\n'+(assets/'android-music.css').read_text()+EXTRA_CSS
content='<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Setwerk – Musiksteuerung Vorschau</title><style>'+styles+'</style></head>'+BODY
content+=''.join(script(name) for name in ['exercises.js','exercises-en.js','i18n.js','core.js','transfer.js'])
content+='<script>'+FIXTURE+'</script>'+script('app.js')+script('android-music.js')+'</body></html>'
Path(a.output).resolve().write_text(content)
print('Created music preview:',Path(a.output).resolve())
